INSERT INTO `community_posts` (`id`, `channel_id`, `category`, `user_id`, `user_type`, `post_text`, `post_type`, `media_url`, `location`, `likes_count`, `comments_count`, `shares_count`, `visibility`, `comment_section`, `is_pinned`, `scheduled_time`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, NULL, 266, 'user', 'What to know\n\nDogs can sometimes carry germs that can make people and other animals sick.\n\nWash your hands after handling your dog, its food, waste, or supplies.\n\nProvide routine veterinary care for your dog to keep it healthy and prevent the spread of diseases.\n\nAlways supervise young children around dogs, even trusted family pets.\n\n', 'image', NULL, 'Telangana', 3, 0, 0, NULL, 0, NULL, NULL, 'active', '2026-04-28 10:17:32', '2026-06-05 17:48:37'),
(2, 1, NULL, 142, 'user', 'Hii sir good morning text me at the end of the day of the day of the day of the day of the day of the day of the day of the day of the day of the day of the day of the day 💐💐💐💐💐 God bless you with lots of happiness and prosperity and happiness and prosperity and happiness \n\n\n\nVyshnavi ch and best wishes to you all this is Saiteja and family members and family members and family in life 🧬🧬 God bless you all this year \n\n\nHubby and I am ', 'image', NULL, 'Telangana', 0, 0, 0, NULL, 1, NULL, NULL, 'deleted', '2026-04-28 13:17:34', '2026-04-28 13:18:31'),
(3, 1, NULL, 142, 'user', '', 'image', NULL, '', 0, 0, 0, NULL, NULL, NULL, NULL, 'deleted', '2026-04-28 14:42:38', '2026-04-28 15:09:54'),
(4, 1, NULL, 142, 'user', '', 'image', NULL, '', 1, 0, 0, NULL, NULL, NULL, NULL, 'deleted', '2026-04-28 15:21:23', '2026-04-29 12:44:35'),
(5, 1, NULL, 266, 'user', 'Dogs are highly intelligent, social animals domesticated over 20,000 years ago, often called \"man\'s best friend\" due to their loyalty and unique ability to understand human communication. With over 340 breeds worldwide, they offer companionship, protection, and assistance. Dogs are notable for their powerful sense of smell and ability to sense human emotions. ', 'image', NULL, 'Telangana', 2, 0, 0, NULL, NULL, NULL, NULL, 'active', '2026-04-28 17:56:07', '2026-06-15 15:55:32'),
(6, 1, NULL, 26, 'admin', '“My dog learned a new trick today!”\r\nFinally got Bruno to sit and shake hands 🐾\r\nTook 3 days and lots of treats 😅\r\nAnyone else training their pets right now?', 'text', NULL, NULL, 2, 0, 0, 'public', NULL, 0, NULL, 'deleted', '2026-04-29 14:44:04', '2026-05-04 14:36:45'),
(7, 1, NULL, 142, 'user', '', 'image', NULL, 'Telangana', 0, 0, 0, NULL, NULL, NULL, NULL, 'deleted', '2026-04-29 15:15:39', '2026-04-29 15:54:35'),
