INSERT INTO `verification_questions` (`id`, `service_id`, `category_name`, `category_weight`, `question_text`, `hint_text`, `options`, `weight`, `is_trigger`, `is_dependent`, `sort_order`, `status`, `field_name`, `training_type`, `created_at`, `updated_at`) VALUES
(1, 4, 'Behaviour, Psychology & Pet Handling', 30.00, 'TEST-v2: Why did you choose to work with pets?', 'I genuinely love animals, feel comfortable around dogs, and enjoy taking care of them.', 'Bad,Poor,Average,Good,Excellent', 2.00, 0, 0, 1, 'active', 'q_why_work_with_pets', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(2, 4, 'Behaviour, Psychology & Pet Handling', 30.00, 'If a dog tries to bite or misbehaves, what will you do?', 'I will stay calm, avoid shouting or hitting, give the dog space, and try to control the situation safely.', 'Bad,Poor,Average,Good,Excellent', 5.00, 1, 0, 2, 'active', 'q_handle_bite', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(3, 4, 'Behaviour, Psychology & Pet Handling', 30.00, 'How do you handle a scared dog?', 'I will approach slowly, speak gently, avoid forcing interaction, and give the dog time to trust me.', 'Bad,Poor,Average,Good,Excellent', 4.00, 0, 0, 3, 'active', 'q_handle_scared', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(4, 4, 'Behaviour, Psychology & Pet Handling', 30.00, 'What signs show you that a dog is stressed or uncomfortable?', 'Tail tucked, avoiding eye contact, lip licking, growling, moving away, nervous behaviour.', 'Bad,Poor,Average,Good,Excellent', 5.00, 0, 0, 4, 'active', 'q_stress_signs', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(5, 4, 'Behaviour, Psychology & Pet Handling', 30.00, 'What basic precautions do you take before starting service with a new dog?', 'I observe the dog’s behaviour, check leash and surroundings, and make the dog comfortable first.', 'Bad,Poor,Average,Good,Excellent', 4.00, 0, 0, 5, 'active', 'q_precautions', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(6, 4, 'Behaviour, Psychology & Pet Handling', 30.00, 'What should you never do while handling a dog?', 'Never shout, hit, scare, pull harshly, or force the dog.', 'Bad,Poor,Average,Good,Excellent', 3.00, 0, 0, 6, 'active', 'q_never_do', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(7, 4, 'Behaviour, Psychology & Pet Handling', 30.00, 'How do you make a new dog comfortable in the first few minutes?', 'I give the dog space, let it smell me, speak softly, and avoid sudden actions.', 'Bad,Poor,Average,Good,Excellent', 3.00, 0, 0, 7, 'active', 'q_make_comfortable', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(8, 4, 'Behaviour, Psychology & Pet Handling', 30.00, 'Can you share one difficult situation you faced with a dog and how you handled it?', 'Real situation handled calmly, patiently, and safely without aggression.', 'Bad,Poor,Average,Good,Excellent', 4.00, 0, 0, 8, 'active', 'q_difficult_situation', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(9, 4, 'Experience', 20.00, 'Do you have experience handling dogs?', 'Yes, I have practical experience handling dogs.', 'Bad,Poor,Average,Good,Excellent', 8.00, 1, 0, 9, 'active', 'q_has_exp', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(10, 4, 'Experience', 20.00, 'How many years of experience do you have with dogs?', 'Clear hands-on experience explanation with confidence.', 'Bad,Poor,Average,Good,Excellent', 7.00, 0, 1, 10, 'active', 'q_years_exp', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(11, 4, 'Experience', 20.00, 'Do you own or have you owned a pet?', 'Yes, I understand pet behaviour and responsibilities.', 'Bad,Poor,Average,Good,Excellent', 5.00, 0, 0, 11, 'active', 'q_own_pet', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(12, 4, 'Job Commitment', 15.00, 'Is this full-time or part-time for you? How serious are you about this work?', 'I am serious about this work and can commit consistently.', 'Bad,Poor,Average,Good,Excellent', 8.00, 0, 0, 12, 'active', 'q_commitment', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(13, 4, 'Job Commitment', 15.00, 'Do you agree to follow Petsfolio rules and not take clients offline?', 'Yes, I will strictly follow Petsfolio policies.', 'Bad,Poor,Average,Good,Excellent', 7.00, 0, 0, 13, 'active', 'q_follow_rules', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(14, 4, 'Situational Safety & Presence of Mind', 15.00, 'If the dog suddenly runs away during a walk, what will you do?', 'I will stay calm, safely try to stop/call the dog, and immediately inform the client and team if needed.', 'Bad,Poor,Average,Good,Excellent', 3.00, 0, 0, 14, 'active', 'q_run_away_action', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(15, 4, 'Situational Safety & Presence of Mind', 15.00, 'What precautions will you take to ensure the dog does NOT run away during a walk?', 'Proper leash grip, staying alert, avoiding distractions, and choosing safe routes.', 'Bad,Poor,Average,Good,Excellent', 3.00, 0, 0, 15, 'active', 'q_prevent_run_away', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(16, 4, 'Situational Safety & Presence of Mind', 15.00, 'If another dog tries to attack the dog you are handling, what will you do?', 'I will calmly move away, protect the dog, and avoid panic.', 'Bad,Poor,Average,Good,Excellent', 2.00, 0, 0, 16, 'active', 'q_dog_attack_action', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
(17, 4, 'Situational Safety & Presence of Mind', 15.00, 'What precautions will you take to avoid fights or attacks from other dogs during a walk?', 'I will maintain distance from unknown dogs and stay aware of surroundings.', 'Bad,Poor,Average,Good,Excellent', 2.00, 0, 0, 17, 'active', 'q_prevent_attacks', NULL, '2026-07-01 17:50:16', '2026-07-01 17:50:16'),
